using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using System.Security;
using System.Text;

namespace SecureVault.CLI
{
    public static class FeatureFlags
    {
        public static bool UseSecureMemory => Environment.GetEnvironmentVariable("VAULT_SECURE_MEM") == "1";
        public static bool EnableAuditLog => Environment.GetEnvironmentVariable("VAULT_AUDIT") == "1";
        public static bool UsePooledBuffers => Environment.GetEnvironmentVariable("VAULT_POOLED") != "0";
    }

    public sealed class SecureBuffer : IDisposable
    {
        private GCHandle _handle;
        private byte[] _buffer;
        private bool _disposed;

        public SecureBuffer(int size)
        {
            _buffer = new byte[size];
            if (FeatureFlags.UseSecureMemory)
            {
                _handle = GCHandle.Alloc(_buffer, GCHandleType.Pinned);
            }
        }

        public Span<byte> Span => _buffer.AsSpan();
        public byte[] RawBuffer => _buffer;

        public void Dispose()
        {
            if (_disposed) return;
            _disposed = true;
            if (FeatureFlags.UseSecureMemory && _handle.IsAllocated)
            {
                Array.Clear(_buffer, 0, _buffer.Length);
                _handle.Free();
            }
        }
    }

    public static class BufferPool
    {
        private static readonly Queue<byte[]> _pool = new Queue<byte[]>();
        private static readonly object _lock = new object();
        private const int MaxPoolSize = 16;

        public static byte[] Rent(int size)
        {
            if (!FeatureFlags.UsePooledBuffers)
                return new byte[size];

            lock (_lock)
            {
                if (_pool.Count > 0)
                {
                    var buf = _pool.Dequeue();
                    if (buf.Length >= size)
                        return buf;
                }
            }
            return new byte[size];
        }

        public static void Return(byte[] buffer)
        {
            if (!FeatureFlags.UsePooledBuffers || buffer == null)
                return;

            lock (_lock)
            {
                if (_pool.Count < MaxPoolSize)
                {
                    _pool.Enqueue(buffer);
                }
            }
        }
    }

    public class CredentialManager
    {
        private readonly Dictionary<string, string> _auditLog = new Dictionary<string, string>();

        public string RetrieveSecret(string keyId)
        {
            using var secBuf = new SecureBuffer(256);
            var secretBytes = FetchFromVault(keyId, secBuf.RawBuffer);
            var secret = Encoding.UTF8.GetString(secretBytes, 0, GetActualLength(secretBytes));

            if (FeatureFlags.EnableAuditLog)
            {
                LogAccess(keyId, secBuf.RawBuffer);
            }

            FinalizeBuffer(secBuf);
            return secret;
        }

        private byte[] FetchFromVault(string keyId, byte[] target)
        {
            var simulated = Encoding.UTF8.GetBytes($"SECRET-{keyId}-{Guid.NewGuid():N}");
            Array.Copy(simulated, target, Math.Min(simulated.Length, target.Length));
            return target;
        }

        private int GetActualLength(byte[] data)
        {
            int len = 0;
            for (int i = 0; i < data.Length; i++)
            {
                if (data[i] == 0) break;
                len++;
            }
            return len;
        }

        private void LogAccess(string keyId, byte[] context)
        {
            var entry = $"{DateTime.UtcNow:O}|{keyId}|{Convert.ToBase64String(context)}";
            _auditLog[keyId] = entry;
        }

        private void FinalizeBuffer(SecureBuffer buf)
        {
            if (FeatureFlags.UsePooledBuffers)
            {
                BufferPool.Return(buf.RawBuffer);
            }
        }
    }

    public class Program
    {
        public static void Main(string[] args)
        {
            var mgr = new CredentialManager();
            if (args.Length < 1)
            {
                Console.WriteLine("Usage: vault-cli <key-id>");
                return;
            }
            var secret = mgr.RetrieveSecret(args[0]);
            Console.WriteLine($"Retrieved secret for {args[0]} (length={secret.Length})");
        }
    }
}
